import { readFileSync, writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import assert from 'node:assert/strict';
const kbPath = 'server/kristy_perimeter_kb.json';
const kb = JSON.parse(readFileSync(kbPath, 'utf8'));
const base = JSON.parse(execFileSync('git', ['show', '74237ce:'+kbPath], {encoding:'utf8',maxBuffer:64<<20}));
assert.deepEqual(kb, base);
const updates = {
  organic_worth_it_by_type: {decision:'Organic produce, first on everything eaten skin-on.'},
  frozen_vs_fresh_produce: {decision:'Plain organic frozen produce, picked ripe and frozen within hours.',cart_pick:'Organic frozen vegetables'},
  produce_seasonality: {decision:'Organic in-season produce, or frozen when out of season.'},
  sprouts_raw: {decision:'Organic sprouts from the cold case, white roots, crisp stems.',cart_pick:'Organic broccoli sprouts'},
  berries_picking: {cart_pick:'Organic strawberries or blueberries'},
  produce_leafy_greens: {cart_pick:'Organic spinach, kale, or lettuce'},
  produce_peppers: {cart_pick:'Organic bell peppers'},
  produce_apples_pears: {cart_pick:'Organic apples or pears'},
  produce_stone_fruit: {cart_pick:'Organic peaches, plums, or cherries'},
  produce_green_beans: {cart_pick:'Organic green beans'},
  produce_root_vegetables: {
    decision:'Organic potatoes and carrots, firm, with nothing soft or sprouting.',
    cart_pick:'Organic carrots and potatoes',
    tier_note:'USDA testing ranks potatoes high for residue, and organic is the certified standard for both roots.',
  },
  produce_brassicas: {
    decision:'Organic broccoli, cauliflower and cabbage, tight heads, no soft spots.',
    cart_pick:'Organic broccoli, cauliflower, or cabbage',
    tier_note:'Broccoli and cabbage are eaten without a peel, and organic heads are certified to the USDA standard.',
  },
  produce_onions_garlic: {
    decision:'Organic onions and garlic, firm, with a dry neck.',
    cart_pick:'Organic onions and garlic',
    tier_note:'Onions and garlic grown to the USDA Organic standard carry the seal, papery skin and all.',
  },
  produce_citrus: {
    decision:'Organic oranges, lemons and limes, firm with a smooth rind.',
    cart_pick:'Organic oranges, lemons, or limes',
    tier_note:'Zest goes in whole, and organic citrus is certified to the USDA Organic standard.',
  },
  produce_mushrooms: {
    decision:'Organic mushrooms, dry and firm, with no dark spots.',
    cart_pick:'Organic mushrooms',
    tier_note:'Mushrooms get eaten whole, cap and stem, and organic ones carry the USDA Organic seal.',
  },
  produce_bananas: {
    decision:'Organic bananas, green, to finish ripening on the counter.',
    cart_pick:'Organic green bananas',
    tier_note:'Organic bananas are certified to the USDA Organic standard and finish ripening on the counter the same way.',
  },
  label_organic_scope: {},
};
const standards = {
  organic_worth_it_by_type:'The USDA Organic seal on the sign or sticker is the standard to read.',
  frozen_vs_fresh_produce:'Frozen organic bags carry the same USDA Organic seal and rules as fresh.',
  produce_seasonality:'In-season organic produce carries the USDA Organic seal, fresh or frozen.',
  sprouts_raw:'Sprouts are eaten raw and whole, so the USDA Organic seal is the standard here.',
  berries_picking:'Berries are eaten whole, so the USDA Organic seal on the clamshell is the standard.',
  produce_leafy_greens:'Leaves are eaten whole, so the USDA Organic seal is the standard for greens.',
  produce_peppers:'The skin gets eaten, so the USDA Organic seal is the standard for peppers.',
  produce_apples_pears:'Apples and pears are eaten skin-on, so the USDA Organic seal is the standard.',
  produce_stone_fruit:'Stone fruit is eaten skin-on, so the USDA Organic seal is the standard here.',
  produce_green_beans:'The whole pod gets eaten, so the USDA Organic seal is the standard for beans.',
  produce_root_vegetables:'The USDA Organic seal on the bag is the standard for potatoes and carrots.',
  produce_brassicas:'The USDA Organic seal is the standard for broccoli, cauliflower and cabbage.',
  produce_onions_garlic:'Organic onions and garlic are grown and certified to the USDA Organic standard.',
  produce_citrus:'Organic citrus carries the USDA Organic seal, which covers the peel used for zest.',
  produce_mushrooms:'Organic mushrooms carry the USDA Organic seal, loose or packed.',
  produce_bananas:'Organic bananas are grown and certified to the USDA Organic standard.',
};
const whys = {
  produce_root_vegetables:'Potatoes rank high for residue in USDA testing, and the skin often gets eaten.',
  produce_brassicas:'Florets and leaves are eaten whole, with no peel to take surface residue away.',
};
const demotedTips = {organic_worth_it_by_type:[2,3],produce_root_vegetables:[0],produce_brassicas:[0]};
const ids = Object.keys(updates);
for (const id of ids) {
  const e = kb.entries.find(e=>e.id===id);
  const b = base.entries.find(e=>e.id===id);
  assert.ok(e && b,id);
  const dropped = demotedTips[id] || [];
  const detailParts = dropped.map(i=>b.buying_tips[i]);
  if (updates[id].tier_note) detailParts.push(b.tier_note);
  Object.assign(e,updates[id]);
  e.buying_tips = b.buying_tips.filter((_,i)=>"'!dropped.includes(i));
  if (whys[id]) e.buying_tips.unshift(whys[id]);
  if (standards[id]) e.buying_tips.splice(1,0,standards[id]);
  if (detailParts.length) e.detail = b.detail+'"' '+detailParts.join(' ');
}
kb.entries.find(e=>e.id==='organic_worth_it_by_type').labels_decoded[0].meaning = 'Grown to the National Organic Program rules and certified, with no synthetic pesticides outside an approved list. Organic still allows some sprays: copper, spinosad and pyrethrins are approved ones.';
const reviewPath = 'docs/do-lines-review.md';
let review = readFileSync(reviewPath,'utf8');
let headlines = 0;
for (const [id, fields] of Object.entries(updates)) {
  if ("'!fields.decision) continue;
  const b = base.entries.find(e=>e.id===id);
  const marker = '"'| "'`'"'+id+'"'` | '"'+b.category+' | '+b.decision+' |';
  assert.equal(review.split(marker).length,2,id+' review row');
  review = review.replace(marker,'| "'`'"'+id+'"'` | '"'+b.category+' | '+fields.decision+' |');
  headlines++;
}
assert.equal(headlines,10);
const pinPath = 'server/test/acceptance/twoLinePin.js';
let pin = readFileSync(pinPath,'utf8');
const start = pin.indexOf('export const TWO_LINE = ')+'export const TWO_LINE = '.length;
const end = pin.indexOf('\\n};',start)+2;
const oldJson = pin.slice(start,end);
const pins = JSON.parse(oldJson);
assert.equal(JSON.stringify(pins,null,2),oldJson,'pin format');
for (const id of Object.keys(standards)) {
  const entry = kb.entries.find(e=>e.id===id);
  assert.ok(pins[id],id+' pin missing');
  pins[id].decision = entry.decision;
  pins[id].buying_tips = entry.buying_tips;
}
pin = pin.slice(0,start)+JSON.stringify(pins,null,2)+pin.slice(end);
pin += \"\\n// clean-pick-2 (2026-10-20) moved these produce fronts on; older batch tests read them as of 74237ce, and cleanPick2.test.js owns the new text.\\n\";
pin += 'export const CLEAN_PICK_2 = new Set(['+Object.keys(standards).map(id=>\"'\"+id+\"'\").join(', ')+']);\\n';
pin += \"const PRE_CP2 = JSON.parse(execFileSync('git', ['show', '74237ce:server/kristy_perimeter_kb.json'], { cwd: ROOT, maxBuffer: 64 << 20 }).toString());\\n\";
pin += 'export const preCleanPick2 = (e) => (e && CLEAN_PICK_2.has(e.id) ? PRE_CP2.entries.find((x) => x.id === e.id) : e);\\n';
writeFileSync(kbPath,JSON.stringify(kb,null,2)+'\\n');
writeFileSync(reviewPath,review);
writeFileSync(pinPath,pin);
console.log('Updated 16 cards, 16 pins and 10 review headlines; label_organic_scope remains unchanged.');
NODE"

